import csv, json

RESEARCH = {"E01","E03","E05","E07","E09"}
TIER_A = {"Berlin","Geneva","London","New York","Paris","Tokyo","Zurich"}
TIER_B = {"Austin","Lisbon","Madrid","Manchester","Osaka"}
CAPS = {"meals": {"A":60,"B":40}, "lodging": {"A":220,"B":140}, "taxi": {"A":50,"B":50}}

violations = set()
by_emp = {}

with open("/app/data/claims.csv") as f:
    for r in csv.DictReader(f):
        if r["employee_id"] not in RESEARCH: continue
        if not ("2026-09-01" <= r["date"] <= "2026-09-30"): continue
        cid, emp, cat = r["claim_id"], r["employee_id"], r["category"]
        amt = float(r["amount"])  # all EUR
        reimb = 0.0
        if cat == "flights":
            if r["approval_id"].strip():
                reimb = amt
            else:
                violations.add(cid)
        else:
            tier = "A" if r["city"] in TIER_A else "B" if r["city"] in TIER_B else None
            cap = CAPS[cat][tier]
            if amt > cap:
                reimb = float(cap); violations.add(cid)
            else:
                reimb = amt
            if amt > 40 and r["receipt"].strip().lower() != "yes":
                reimb = 0.0; violations.add(cid)
        by_emp[emp] = by_emp.get(emp, 0.0) + reimb

total = sum(by_emp.values())
out = {
    "violations": sorted(violations),
    "by_employee": {e: round(v,2) for e,v in sorted(by_emp.items())},
    "reimbursable_eur": round(total,2),
}
json.dump(out, open("/app/output/expense_report.json","w"), indent=2)
print(json.dumps(out, indent=2))
EOF
