import csv, json
from decimal import Decimal, ROUND_HALF_UP

# FX rates (only needed for non-EUR, but load anyway)
fx = {}
with open('/app/finance/fx_rates.csv') as f:
    for r in csv.DictReader(f):
        fx[(r['date'], r['currency'])] = Decimal(r['eur_per_unit'])
# corrections
fx[('2026-08-04','GBP')] = Decimal('1.2183')

research = set()
with open('/app/data/employees.csv') as f:
    for r in csv.DictReader(f):
        if r['department'].strip()=='Research':
            research.add(r['employee_id'])
print('research:', sorted(research))

def D(x): return Decimal(x)
def r2(x): return x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

tierA = {'Berlin','Geneva','London','New York','Paris','Tokyo','Zurich'}
tierB = {'Austin','Lisbon','Madrid','Manchester','Osaka'}
caps = {('meals','A'):D(60),('meals','B'):D(40),('lodging','A'):D(220),('lodging','B'):D(140),('taxi','A'):D(50),('taxi','B'):D(50)}

viol=set()
by_emp={}
for r in csv.DictReader(open('/app/data/claims.csv')):
    if r['employee_id'] not in research: continue
    d=r['date']
    if not ('2026-09-01'<=d<='2026-09-30'): continue
    cur=r['currency']; amt=D(r['amount'])
    if cur=='EUR': eur=amt
    else: eur=r2(amt*fx[(d,cur)])
    cat=r['category']; city=r['city']
    is_viol=False
    if cat=='flights':
        if not r['approval_id'].strip():
            is_viol=True
        reimb=eur if not is_viol else D(0)
    else:
        tier='A' if city in tierA else ('B' if city in tierB else None)
        cap=caps[(cat,tier)]
        if eur>cap:
            is_viol=True; reimb=cap
        else:
            reimb=eur
        # receipt
        if eur>D(30) and r['receipt'].strip()!='yes':
            is_viol=True; reimb=D(0)
    if is_viol: viol.add(r['claim_id'])
    by_emp[r['employee_id']]=by_emp.get(r['employee_id'],D(0))+reimb

by_emp={k:r2(v) for k,v in by_emp.items()}
total=r2(sum(by_emp.values()))
print(json.dumps({"violations":sorted(viol),"by_employee":{k:str(v) for k,v in sorted(by_emp.items())},"reimbursable_eur":str(total)}))

# save
csv_out={"violations":sorted(viol),"by_employee":{k:float(v) for k,v in sorted(by_emp.items())},"reimbursable_eur":float(total)}
import os; os.makedirs('/app/output',exist_ok=True)
with open('/app/output/expense_report.json','w') as f:
    json.dump(csv_out,f,indent=2)
print('written')
EOF
