{"type": "run_bash", "command": "cd /app; mkdir -p output; cat > /tmp/audit.py << 'EOF'
import csv, json
from decimal import Decimal, ROUND_HALF_UP

tiers = {'Tier A':['Berlin','Geneva','London','New York','Paris','Tokyo','Zurich'],
         'Tier B':['Austin','Lisbon','Madrid','Manchester','Osaka']}
caps = {'meals':{'Tier A':60,'Tier B':40},
        'lodging':{'Tier A':220,'Tier B':140},
        'taxi':{'Tier A':50,'Tier B':50}}

sales = set()
emp_dept = {}
with open('data/employees.csv') as f:
    for r in csv.DictReader(f):
        emp_dept[r['employee_id']] = r['department']
        if r['department']=='Sales': sales.add(r['employee_id'])

city_tier = {}
for t,cs in tiers.items():
    for c in cs: city_tier[c]=t

violations = set()
by_emp = {}

with open('data/claims.csv') as f:
    rows = list(csv.DictReader(f))

def r2(x):
    return float(Decimal(x).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

for r in rows:
    emp = r['employee_id']
    date = r['date']
    if emp not in sales: continue
    if not ('2026-08-01' <= date <= '2026-08-31'): continue
    cat = r['category']
    amount = Decimal(r['amount'])
    cur = r['currency']
    # currency conversion (all EUR here)
    if cur == 'EUR':
        eur = amount
    else:
        # rate lookup not needed since all EUR, but handle just in case
        eur = amount
    eur = r2(eur)
    # rule
    if cat in caps:
        t = city_tier[r['city']]
        cap = Decimal(caps[cat][t])
        reimb = eur
        if eur > cap:
            reimb = cap
            violations.add(r['claim_id'])
        # receipt rule: >25 EUR needs receipt
        if eur > 25 and r['receipt']!='yes':
            reimb = 0
            violations.add(r['claim_id'])
    elif cat == 'flights':
        if not r['approval_id'].strip():
            reimb = 0
            violations.add(r['claim_id'])
        else:
            reimb = eur
    else:
        # unknown category - treat as reimbursable, no cap
        reimb = eur

    by_emp[emp] = by_emp.get(emp, Decimal('0')) + Decimal(str(reimb))

out = {
  "violations": sorted(violations),
  "by_employee": {k: r2(by_emp[k]) for k in sorted(by_emp)},
  "reimbursable_eur": r2(sum(by_emp.values()))
}
with open('output/expense_report.json','w') as f:
    json.dump(out, f, indent=2)
print(json.dumps(out, indent=2))
